49	/**
50	 * Contains the logic to lookup a leveldb by timestamp so that multiple smaller
51	 * databases can roll according to the configured period and evicted efficiently
52	 * via operating system directory removal.
53	 */
54	class RollingLevelDB {
55	
56	  /** Logger for this class. */
57	  private static final Logger LOG = LoggerFactory.
58	      getLogger(RollingLevelDB.class);
59	  /** Factory to open and create new leveldb instances. */
60	  private static JniDBFactory factory = new JniDBFactory();
61	  /** Thread safe date formatter. */
62	  private FastDateFormat fdf;
63	  /** Date parser. */
64	  private SimpleDateFormat sdf;
65	  /** Calendar to calculate the current and next rolling period. */
66	  private GregorianCalendar cal = new GregorianCalendar(
67	      TimeZone.getTimeZone("GMT"));
68	  /** Collection of all active rolling leveldb instances. */
69	  private final TreeMap<Long, DB> rollingdbs;
70	  /** Collection of all rolling leveldb instances to evict. */
71	  private final TreeMap<Long, DB> rollingdbsToEvict;
72	  /** Name of this rolling level db. */
73	  private final String name;
74	  /** Calculated timestamp of when to roll a new leveldb instance. */
75	  private volatile long nextRollingCheckMillis = 0;
76	  /** File system instance to find and create new leveldb instances. */
77	  private FileSystem lfs = null;
78	  /** Directory to store rolling leveldb instances. */
79	  private Path rollingDBPath;
80	  /** Configuration for this object. */
81	  private Configuration conf;
82	  /** Rolling period. */
83	  private RollingPeriod rollingPeriod;
84	  /**
85	   * Rolling leveldb instances are evicted when their endtime is earlier than
86	   * the current time minus the time to live value.
87	   */
88	  private long ttl;
89	  /** Whether time to live is enabled. */
90	  private boolean ttlEnabled;
91	
92	  /** Encapsulates the rolling period to date format lookup. */
93	  enum RollingPeriod {
94	    DAILY {
95	      @Override
96	      public String dateFormat() {
97	        return "yyyy-MM-dd";
98	      }
99	    },
100	    HALF_DAILY {
101	      @Override
102	      public String dateFormat() {
103	        return "yyyy-MM-dd-HH";
104	      }
105	    },
106	    QUARTER_DAILY {
107	      @Override
108	      public String dateFormat() {
109	        return "yyyy-MM-dd-HH";
110	      }
111	    },
112	    HOURLY {
113	      @Override
114	      public String dateFormat() {
115	        return "yyyy-MM-dd-HH";
116	      }
117	    },
118	    MINUTELY {
119	      @Override
120	      public String dateFormat() {
121	        return "yyyy-MM-dd-HH-mm";
122	      }
123	    };
124	    public abstract String dateFormat();
125	  }
126	
127	  /**
128	   * Convenience class for associating a write batch with its rolling leveldb
129	   * instance.
130	   */
131	  public static class RollingWriteBatch {
132	    /** Leveldb object. */
133	    private final DB db;
134	    /** Write batch for the db object. */
135	    private final WriteBatch writeBatch;
136	
137	    public RollingWriteBatch(final DB db, final WriteBatch writeBatch) {
138	      this.db = db;
139	      this.writeBatch = writeBatch;
140	    }
141	
142	    public DB getDB() {
143	      return db;
144	    }
145	
146	    public WriteBatch getWriteBatch() {
147	      return writeBatch;
148	    }
149	
150	    public void write() {
151	      db.write(writeBatch);
152	    }
153	
154	    public void close() {
155	      IOUtils.cleanupWithLogger(LOG, writeBatch);
156	    }
157	  }
158	
159	  RollingLevelDB(String name) {
160	    this.name = name;
161	    this.rollingdbs = new TreeMap<Long, DB>();
162	    this.rollingdbsToEvict = new TreeMap<Long, DB>();
163	  }
164	
165	  protected String getName() {
166	    return name;
167	  }
168	
169	  protected long currentTimeMillis() {
170	    return System.currentTimeMillis();
171	  }
172	
173	  public long getNextRollingTimeMillis() {
174	    return nextRollingCheckMillis;
175	  }
176	
177	  public long getTimeToLive() {
178	    return ttl;
179	  }
180	
181	  public boolean getTimeToLiveEnabled() {
182	    return ttlEnabled;
183	  }
184	
185	  protected void setNextRollingTimeMillis(final long timestamp) {
186	    this.nextRollingCheckMillis = timestamp;
187	    LOG.info("Next rolling time for " + getName() + " is "
188	        + fdf.format(nextRollingCheckMillis));
189	  }
190	
191	  public void init(final Configuration config) throws Exception {
192	    LOG.info("Initializing RollingLevelDB for " + getName());
193	    this.conf = config;
194	    this.ttl = conf.getLong(YarnConfiguration.TIMELINE_SERVICE_TTL_MS,
195	        YarnConfiguration.DEFAULT_TIMELINE_SERVICE_TTL_MS);
196	    this.ttlEnabled = conf.getBoolean(
197	        YarnConfiguration.TIMELINE_SERVICE_TTL_ENABLE, true);
198	    this.rollingDBPath = new Path(
199	        conf.get(YarnConfiguration.TIMELINE_SERVICE_LEVELDB_PATH),
200	        RollingLevelDBTimelineStore.FILENAME);
201	    initFileSystem();
202	    initRollingPeriod();
203	    initHistoricalDBs();
204	  }
205	
206	  protected void initFileSystem() throws IOException {
207	    lfs = FileSystem.getLocal(conf);
208	    boolean success = lfs.mkdirs(rollingDBPath,
209	        RollingLevelDBTimelineStore.LEVELDB_DIR_UMASK);
210	    if (!success) {
211	      throw new IOException("Failed to create leveldb root directory "
212	          + rollingDBPath);
213	    }
214	  }
215	
216	  protected synchronized void initRollingPeriod() {
217	    final String lcRollingPeriod = conf.get(
218	        YarnConfiguration.TIMELINE_SERVICE_ROLLING_PERIOD,
219	        YarnConfiguration.DEFAULT_TIMELINE_SERVICE_ROLLING_PERIOD);
220	    this.rollingPeriod = RollingPeriod.valueOf(lcRollingPeriod
221	        .toUpperCase(Locale.ENGLISH));
222	    fdf = FastDateFormat.getInstance(rollingPeriod.dateFormat(),
223	        TimeZone.getTimeZone("GMT"));
224	    sdf = new SimpleDateFormat(rollingPeriod.dateFormat());
225	    sdf.setTimeZone(fdf.getTimeZone());
226	  }
227	
228	  protected synchronized void initHistoricalDBs() throws IOException {
229	    Path rollingDBGlobPath = new Path(rollingDBPath, getName() + ".*");
230	    FileStatus[] statuses = lfs.globStatus(rollingDBGlobPath);
231	    for (FileStatus status : statuses) {
232	      String dbName = FilenameUtils.getExtension(status.getPath().toString());
233	      try {
234	        Long dbStartTime = sdf.parse(dbName).getTime();
235	        initRollingLevelDB(dbStartTime, status.getPath());
236	      } catch (ParseException pe) {
237	        LOG.warn("Failed to initialize rolling leveldb " + dbName + " for "
238	            + getName());
239	      }
240	    }
241	  }
242	
243	  private void initRollingLevelDB(Long dbStartTime,
244	      Path rollingInstanceDBPath) {
245	    if (rollingdbs.containsKey(dbStartTime)) {
246	      return;
247	    }
248	    Options options = new Options();
249	    options.createIfMissing(true);
250	    options.cacheSize(conf.getLong(
251	        YarnConfiguration.TIMELINE_SERVICE_LEVELDB_READ_CACHE_SIZE,
252	        YarnConfiguration.DEFAULT_TIMELINE_SERVICE_LEVELDB_READ_CACHE_SIZE));
253	    options.maxOpenFiles(conf.getInt(
254	        YarnConfiguration.TIMELINE_SERVICE_LEVELDB_MAX_OPEN_FILES,
255	        YarnConfiguration.DEFAULT_TIMELINE_SERVICE_LEVELDB_MAX_OPEN_FILES));
256	    options.writeBufferSize(conf.getInt(
257	        YarnConfiguration.TIMELINE_SERVICE_LEVELDB_WRITE_BUFFER_SIZE,
258	        YarnConfiguration.DEFAULT_TIMELINE_SERVICE_LEVELDB_WRITE_BUFFER_SIZE));
259	    LOG.info("Initializing rolling leveldb instance :" + rollingInstanceDBPath
260	        + " for start time: " + dbStartTime);
261	    DB db = null;
262	    try {
263	      db = factory.open(
264	          new File(rollingInstanceDBPath.toUri().getPath()), options);
265	      rollingdbs.put(dbStartTime, db);
266	      String dbName = fdf.format(dbStartTime);
267	      LOG.info("Added rolling leveldb instance " + dbName + " to " + getName());
268	    } catch (IOException ioe) {
269	      LOG.warn("Failed to open rolling leveldb instance :"
270	          + new File(rollingInstanceDBPath.toUri().getPath()), ioe);
271	    }
272	  }
273	
274	  synchronized DB getPreviousDB(DB db) {
275	    Iterator<DB> iterator = rollingdbs.values().iterator();
276	    DB prev = null;
277	    while (iterator.hasNext()) {
278	      DB cur = iterator.next();
279	      if (cur == db) {
280	        break;
281	      }
282	      prev = cur;
283	    }
284	    return prev;
285	  }
286	
287	  synchronized long getStartTimeFor(DB db) {
288	    long startTime = -1;
289	    for (Map.Entry<Long, DB> entry : rollingdbs.entrySet()) {
290	      if (entry.getValue() == db) {
291	        startTime = entry.getKey();
292	      }
293	    }
294	    return startTime;
295	  }
296	
297	  public synchronized DB getDBForStartTime(long startTime) {
298	    // make sure we sanitize this input
299	    startTime = Math.min(startTime, currentTimeMillis());
300	
301	    if (startTime >= getNextRollingTimeMillis()) {
302	      roll(startTime);
303	    }
304	    Entry<Long, DB> entry = rollingdbs.floorEntry(startTime);
305	    if (entry == null) {
306	      return null;
307	    }
308	    return entry.getValue();
309	  }
310	
311	  private void roll(long startTime) {
312	    LOG.info("Rolling new DB instance for " + getName());
313	    long currentStartTime = computeCurrentCheckMillis(startTime);
314	    setNextRollingTimeMillis(computeNextCheckMillis(currentStartTime));
315	    String currentRollingDBInstance = fdf.format(currentStartTime);
316	    String currentRollingDBName = getName() + "." + currentRollingDBInstance;
317	    Path currentRollingDBPath = new Path(rollingDBPath, currentRollingDBName);
318	    if (getTimeToLiveEnabled()) {
319	      scheduleOldDBsForEviction();
320	    }
321	    initRollingLevelDB(currentStartTime, currentRollingDBPath);
322	  }
323	
324	  private synchronized void scheduleOldDBsForEviction() {
325	    // keep at least time to live amount of data
326	    long evictionThreshold = computeCurrentCheckMillis(currentTimeMillis()
327	        - getTimeToLive());
328	
329	    LOG.info("Scheduling " + getName() + " DBs older than "
330	        + fdf.format(evictionThreshold) + " for eviction");
331	    Iterator<Entry<Long, DB>> iterator = rollingdbs.entrySet().iterator();
332	    while (iterator.hasNext()) {
333	      Entry<Long, DB> entry = iterator.next();
334	      // parse this in gmt time
335	      if (entry.getKey() < evictionThreshold) {
336	        LOG.info("Scheduling " + getName() + " eviction for "
337	            + fdf.format(entry.getKey()));
338	        iterator.remove();
339	        rollingdbsToEvict.put(entry.getKey(), entry.getValue());
340	      }
341	    }
342	  }
343	
344	  public synchronized void evictOldDBs() {
345	    LOG.info("Evicting " + getName() + " DBs scheduled for eviction");
346	    Iterator<Entry<Long, DB>> iterator = rollingdbsToEvict.entrySet()
347	        .iterator();
348	    while (iterator.hasNext()) {
349	      Entry<Long, DB> entry = iterator.next();
350	      IOUtils.cleanupWithLogger(LOG, entry.getValue());
351	      String dbName = fdf.format(entry.getKey());
352	      Path path = new Path(rollingDBPath, getName() + "." + dbName);
353	      try {
354	        LOG.info("Removing old db directory contents in " + path);
355	        lfs.delete(path, true);
356	      } catch (IOException ioe) {
357	        LOG.warn("Failed to evict old db " + path, ioe);
358	      }
359	      iterator.remove();
360	    }
361	  }
362	
363	  public void stop() throws Exception {
364	    for (DB db : rollingdbs.values()) {
365	      IOUtils.cleanupWithLogger(LOG, db);
366	    }
367	    IOUtils.cleanupWithLogger(LOG, lfs);
368	  }
369	
370	  private long computeNextCheckMillis(long now) {
371	    return computeCheckMillis(now, true);
372	  }
373	
374	  public long computeCurrentCheckMillis(long now) {
375	    return computeCheckMillis(now, false);
376	  }
377	
378	  private synchronized long computeCheckMillis(long now, boolean next) {
379	    // needs to be called synchronously due to shared Calendar
380	    cal.setTimeInMillis(now);
381	    cal.set(Calendar.SECOND, 0);
382	    cal.set(Calendar.MILLISECOND, 0);
383	
384	    if (rollingPeriod == RollingPeriod.DAILY) {
385	      cal.set(Calendar.HOUR_OF_DAY, 0);
386	      cal.set(Calendar.MINUTE, 0);
387	      if (next) {
388	        cal.add(Calendar.DATE, 1);
389	      }
390	    } else if (rollingPeriod == RollingPeriod.HALF_DAILY) {
391	      // round down to 12 hour interval
392	      int hour = (cal.get(Calendar.HOUR) / 12) * 12;
393	      cal.set(Calendar.HOUR, hour);
394	      cal.set(Calendar.MINUTE, 0);
395	      if (next) {
396	        cal.add(Calendar.HOUR_OF_DAY, 12);
397	      }
398	    } else if (rollingPeriod == RollingPeriod.QUARTER_DAILY) {
399	      // round down to 6 hour interval
400	      int hour = (cal.get(Calendar.HOUR) / 6) * 6;
401	      cal.set(Calendar.HOUR, hour);
402	      cal.set(Calendar.MINUTE, 0);
403	      if (next) {
404	        cal.add(Calendar.HOUR_OF_DAY, 6);
405	      }
406	    } else if (rollingPeriod == RollingPeriod.HOURLY) {
407	      cal.set(Calendar.MINUTE, 0);
408	      if (next) {
409	        cal.add(Calendar.HOUR_OF_DAY, 1);
410	      }
411	    } else if (rollingPeriod == RollingPeriod.MINUTELY) {
412	      // round down to 5 minute interval
413	      int minute = (cal.get(Calendar.MINUTE) / 5) * 5;
414	      cal.set(Calendar.MINUTE, minute);
415	      if (next) {
416	        cal.add(Calendar.MINUTE, 5);
417	      }
418	    }
419	    return cal.getTimeInMillis();
420	  }
421	}
