350	  @Override
351	  protected void serviceStart() throws Exception {
352	    if (getConfig().getBoolean(TIMELINE_SERVICE_TTL_ENABLE, true)) {
353	      deletionThread = new EntityDeletionThread(getConfig());
354	      deletionThread.start();
355	    }
356	    super.serviceStart();
357	  }
358	
359	  @Override
360	  protected void serviceStop() throws Exception {
361	    if (deletionThread != null) {
362	      deletionThread.interrupt();
363	      LOG.info("Waiting for deletion thread to complete its current action");
364	      try {
365	        deletionThread.join();
366	      } catch (InterruptedException e) {
367	        LOG.warn("Interrupted while waiting for deletion thread to complete,"
368	            + " closing db now", e);
369	      }
370	    }
371	    IOUtils.cleanupWithLogger(LOG, domaindb);
372	    IOUtils.cleanupWithLogger(LOG, starttimedb);
373	    IOUtils.cleanupWithLogger(LOG, ownerdb);
374	    entitydb.stop();
375	    indexdb.stop();
376	    super.serviceStop();
377	  }
