/**
 * Opens the leveldb instance stored at the given path. When the existing
 * leveldb files are missing or corrupt, they are backed up and the leveldb
 * instance is recreated so that the timeline service is still able to start.
 *
 * @param dbPath the path of the leveldb instance to open.
 * @param options the leveldb options to open the instance with.
 * @return the opened leveldb instance.
 * @throws IOException if the leveldb instance can neither be opened nor
 *         recreated.
 */
private DB initDb(Path dbPath, Options options) throws IOException {
  File dbFile = new File(dbPath.toString());
  try {
    return factory.open(dbFile, options);
  } catch (IOException ioe) {
    File backupPath = new File(
        dbPath.toString() + BACKUP_EXT + Time.monotonicNow());
    LOG.warn("Incurred exception while loading LevelDb database. Backing "
        + "up at " + backupPath, ioe);
    FileUtils.copyDirectory(dbFile, backupPath);
    try {
      LOG.warn("Going to try repair");
      factory.repair(dbFile, options);
      return factory.open(dbFile, options);
    } catch (IOException repairException) {
      LOG.warn("Failed to repair LevelDb database " + dbFile
          + ", recreating it", repairException);
      FileUtils.deleteDirectory(dbFile);
      return factory.open(dbFile, options);
    }
  }
}

